// SetArea of the address to the related item.
// Sets o.R.Area to related.
// Adds o to related.R.AreaAddresses.
func (o *Address) SetArea(ctx context.Context, exec boil.ContextExecutor, insert bool, related *AddressLocation) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"addresses\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"area_id"}),
		strmangle.WhereClause("\"", "\"", 2, addressPrimaryKeyColumns),
	)
	values := []interface{}{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.AreaID, related.ID)
	if o.R == nil {
		o.R = &addressR{
			Area: related,
		}
	} else {
		o.R.Area = related
	}

	if related.R == nil {
		related.R = &addressLocationR{
			AreaAddresses: AddressSlice{o},
		}
	} else {
		related.R.AreaAddresses = append(related.R.AreaAddresses, o)
	}

	return nil
}

// RemoveArea relationship.
// Sets o.R.Area to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Address) RemoveArea(ctx context.Context, exec boil.ContextExecutor, related *AddressLocation) error {
	var err error

	queries.SetScanner(&o.AreaID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("area_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Area = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.AreaAddresses {
		if queries.Equal(o.AreaID, ri.AreaID) {
			continue
		}

		ln := len(related.R.AreaAddresses)
		if ln > 1 && i < ln-1 {
			related.R.AreaAddresses[i] = related.R.AreaAddresses[ln-1]
		}
		related.R.AreaAddresses = related.R.AreaAddresses[:ln-1]
		break
	}
	return nil
}

