// SetLocationSearchLogs removes all previously related items of the
// address replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Location's LocationSearchLogs accordingly.
// Replaces o.R.LocationSearchLogs with related.
// Sets related.R.Location's LocationSearchLogs accordingly.
func (o *Address) SetLocationSearchLogs(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*SearchLog) error {
	query := "update \"search_logs\" set \"location_id\" = null where \"location_id\" = $1"
	values := []interface{}{o.ID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.LocationSearchLogs {
			queries.SetScanner(&rel.LocationID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Location = nil
		}
		o.R.LocationSearchLogs = nil
	}

	return o.AddLocationSearchLogs(ctx, exec, insert, related...)
}

// RemoveLocationSearchLogs relationships from objects passed in.
// Removes related items from R.LocationSearchLogs (uses pointer comparison, removal does not keep order)
// Sets related.R.Location.
func (o *Address) RemoveLocationSearchLogs(ctx context.Context, exec boil.ContextExecutor, related ...*SearchLog) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.LocationID, nil)
		if rel.R != nil {
			rel.R.Location = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("location_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.LocationSearchLogs {
			if rel != ri {
				continue
			}

			ln := len(o.R.LocationSearchLogs)
			if ln > 1 && i < ln-1 {
				o.R.LocationSearchLogs[i] = o.R.LocationSearchLogs[ln-1]
			}
			o.R.LocationSearchLogs = o.R.LocationSearchLogs[:ln-1]
			break
		}
	}

	return nil
}

// Addresses retrieves all the records using an executor.
func Addresses(mods ...qm.QueryMod) addressQuery {
	mods = append(mods, qm.From("\"addresses\""))
	q := NewQuery(mods...)
	if len(queries.GetSelect(q)) == 0 {
		queries.SetSelect(q, []string{"\"addresses\".*"})
	}

	return addressQuery{q}
}

